<details><summary>Parser test cases</summary>

Positive syntax cases:

```sql
select * from tbl tablesample system (50);
select * from tbl tablesample system (50 percent);
select * from tbl tablesample system (49.9 percent);
select * from tbl tablesample system (120 row);
select * from tbl tablesample bernoulli (50);
select * from tbl tablesample (50);
select * from tbl tablesample (50) repeatable (123456789);
select * from tbl as a tablesample (50);
select * from tbl `tablesample` tablesample (50);
select * from tbl1 tablesample (10), tbl2 tablesample (20);
select * from tbl1 a tablesample (10) join tbl2 b tablesample (20) on a.id <> b.id;
select * from tbl tablesample (50) where id > 20;
select * from tbl partition (p0) tablesample (50);
select * from tbl tablesample ('34'); -- cast the string to a number
select * from tbl tablesample (0 percent);
select * from tbl tablesample (0 rows); -- mssql rejects this but why not
select * from tbl tablesample (100 percent);

-- optional: 
select * from tbl tablesample (33.3 + 44.4);
select * from tbl tablesample (33.3 + 44.4 percent);
select * from tbl tablesample (33 + 44 rows);
select * from tbl tablesample (33 + 44 rows) repeatable (55 + 66);

select * from tbl tablesample (200); -- syntax ok, but runtime error (percent > 100)
select * from tbl tablesample (-10); -- syntax ok, but runtime error (percent < 0)
select * from tbl tablesample (null); -- syntax ok, but runtime error (percent cannot be cast to number)
select * from tbl tablesample (33.3 rows); -- syntax ok, but runtime error (rows is not integer)
select * from tbl tablesample (-4 rows); -- syntax ok, but runtime error (negative rows)
select * from tbl tablesample (50) repeatable ('ssss'); -- syntax ok, but runtime error (seed is not integer)
```

Negative syntax cases:

```sql
select * from tbl tablesample system(50) a;
select * from tbl tablesample (50) partition (p0);
select * from tbl where id > 20 tablesample system(50);
select * from (select * from tbl) a tablesample system(50);
select * from tbl tablesample system(50) tablesample system(50);
select * from tbl tablesample system(50, 50); -- accepted in postgresql but doesn't worth the generalization.
select * from tbl tablesample dhfksdlfljcoew(50);
select * from tbl tablesample system;
select * from tbl tablesample system (33) repeatable;
select 1 from dual tablesample system (50);
```

</details>
